  void SaveProject(){string p=SaveFile("projeto.muworkbench.json","Projeto MU|*.json");if(p==null)return;Guard.Atomic(p,Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new{format=1,server=server.Text,client=client.Text,sqlHost=sqlHost.Text,database=sqlDb.Text})));status.Text="Perfil salvo sem usuário/senha SQL.";}
  void LoadProject(){string p=PickFile("Projeto MU|*.json");if(p!=null)LoadProfile(p);}
  void LoadProfile(string p){var d=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(p));server.Text=(string)d["server"];client.Text=(string)d["client"];sqlHost.Text=d.ContainsKey("sqlHost")?(string)d["sqlHost"]:"";sqlDb.Text=d.ContainsKey("database")?(string)d["database"]:"";OpenProject();}
  void ItemsPage(){var p=Page("Catálogo de itens");itemsGrid=Grid(false);p.Controls.Add(itemsGrid);var b=Bar();itemSearch.Width=270;itemSearch.PlaceholderCompat("Nome, seção ou índice");itemSearch.TextChanged+=(s,e)=>ShowItems(itemSearch.Text);b.Controls.Add(itemSearch);b.Controls.Add(Button("Importar Item.xml",()=>{string f=PickFile("Catálogo XML|*.xml");if(f!=null){catalog.Load(f);ShowItems("");status.Text=catalog.Items.Count+" itens carregados.";}}));p.Controls.Add(b);}
  void LegacyShowItems(string term){if(itemsGrid==null)return;var t=new DataTable();foreach(var n in new[]{"ID","Section","Index","Name","Width","Height"})t.Columns.Add(n);foreach(var d in catalog.Items.Values.OrderBy(i=>i.Id))if(string.IsNullOrWhiteSpace(term)||d.ToString().IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0||d.Id.ToString()==term)t.Rows.Add(d.Id,d.Section,d.Index,d.Name,d.Width,d.Height);itemsGrid.DataSource=t;}
  ItemDef LegacyPickItem(){if(catalog.Items.Count==0)throw new Exception("Importe Item.xml primeiro.");using(var f=new Form{Text="Escolher item",Size=new Size(650,600),StartPosition=FormStartPosition.CenterParent}){var search=new TextBox{Dock=DockStyle.Top};var list=new ListBox{Dock=DockStyle.Fill};Action refresh=()=>{list.BeginUpdate();list.Items.Clear();foreach(var item in catalog.Items.Values.Where(d=>d.ToString().IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0).OrderBy(d=>d.Id))list.Items.Add(item);list.EndUpdate();};search.TextChanged+=(s,e)=>refresh();var ok=new Button{Text="Escolher",Dock=DockStyle.Bottom,DialogResult=DialogResult.OK};list.DoubleClick+=(s,e)=>{if(list.SelectedItem!=null)f.DialogResult=DialogResult.OK;};f.Controls.Add(list);f.Controls.Add(search);f.Controls.Add(ok);refresh();return f.ShowDialog(this)==DialogResult.OK?(ItemDef)list.SelectedItem:null;}}
  void ShopPage(){var p=Page("Lojas NPC");shopGrid=Grid(true);p.Controls.Add(shopGrid);var b=Bar();b.Controls.Add(Button("Abrir loja XML",()=>{string f=PickFile("Loja XML|*.xml");if(f==null)return;shop=new ShopFile();shop.Load(f);shopGrid.DataSource=shop.Table;status.Text=f;}));b.Controls.Add(Button("Adicionar item",()=>{if(shop==null)throw new Exception("Abra uma loja.");var d=PickItem();if(d!=null)shop.Add(d);}));b.Controls.Add(Button("Remover linha",()=>{if(shopGrid.CurrentRow!=null&&!shopGrid.CurrentRow.IsNewRow)shopGrid.Rows.Remove(shopGrid.CurrentRow);}));b.Controls.Add(Button("Validar / exportar",()=>{if(shop==null)throw new Exception("Abra uma loja.");shopGrid.EndEdit();byte[] data=shop.Export(catalog);string f=SaveFile(Path.GetFileName(shop.Source),"Loja XML|*.xml");if(f==null)return;WriteExport(f,data,shop.Source,shop.Original);status.Text="Loja exportada. Aplique na instalação e recarregue Shop no GameServer.";}));p.Controls.Add(b);}
  void WriteExport(string dest,byte[] bytes,string source,byte[] expected){if(Path.GetFullPath(dest).Equals(Path.GetFullPath(source),StringComparison.OrdinalIgnoreCase)){if(!File.ReadAllBytes(source).SequenceEqual(expected))throw new Exception("O arquivo original mudou. Reabra antes de sobrescrever.");Guard.Backup("file",new{path=source,bytes=Convert.ToBase64String(expected)});}Guard.Atomic(dest,bytes);}
  void CashPage(){var p=Page("Cash Shop");cashTabs.Dock=DockStyle.Fill;p.Controls.Add(cashTabs);var b=Bar();b.Controls.Add(Button("Importar arquivo",()=>{string f=PickFile("Cash Shop TXT|*.txt");if(f!=null){string n=Path.GetFileName(f);if(!new[]{"IBSCategory.txt","IBSPackage.txt","IBSProduct.txt","CashShopPackage.txt","CashShopProduct.txt"}.Contains(n,StringComparer.OrdinalIgnoreCase))throw new Exception("Selecione um dos cinco arquivos do catálogo.");cash.Load(f);RefreshCash();}}));b.Controls.Add(Button("Validar catálogo",()=>{EndCash();var errors=cash.Validate(catalog);Report("Diagnóstico Cash Shop",errors.Count==0?"Nenhuma divergência encontrada nos arquivos importados.":string.Join("\r\n",errors));}));b.Controls.Add(Button("Sincronizar preço simples",()=>{EndCash();string id=Ask("ID do pacote","PackageID / MainID");if(id==null)return;decimal price;if(!decimal.TryParse(Ask("Novo preço","Preço inteiro em moeda do catálogo"),out price))return;cash.SetPrice(id,price);status.Text="Preço alterado nos quatro arquivos. Exporte e revise antes de aplicar.";}));b.Controls.Add(Button("Exportar cinco arquivos",()=>ExportCash()));p.Controls.Add(b);}
  void EndCash(){foreach(TabPage page in cashTabs.TabPages)foreach(var g in page.Controls.OfType<DataGridView>()){g.EndEdit();if(g.DataSource!=null)BindingContext[g.DataSource].EndCurrentEdit();}}
  void RefreshCash(){cashTabs.TabPages.Clear();foreach(var file in cash.Files.Values){var page=new TabPage(file.Name);var g=Grid(true);g.DataSource=file.Table;g.AllowUserToAddRows=true;page.Controls.Add(g);cashTabs.TabPages.Add(page);}}
  void ExportCash(){EndCash();if(cash.Files.Count!=5)throw new Exception("Importe os cinco arquivos para exportar o catálogo completo.");string dest=PickFolder("Pasta de saída do catálogo (recomendado: pasta separada)");if(dest==null)return;
   var output=cash.Files.Values.ToDictionary(f=>f.Name,f=>f.Export());foreach(var file in cash.Files.Values)if(Path.GetFullPath(dest).Equals(Path.GetDirectoryName(Path.GetFullPath(file.Source)),StringComparison.OrdinalIgnoreCase))throw new Exception("Escolha uma pasta separada para revisar e distribuir cliente/servidor juntos.");
   var diag=cash.Validate(catalog);foreach(var file in cash.Files.Values){string rel=file.Name.StartsWith("IBS")?"Client":"Server";string path=Path.Combine(dest,rel,file.Name);Guard.Atomic(path,output[file.Name]);}Guard.Atomic(Path.Combine(dest,"DIAGNOSTICO.txt"),Encoding.UTF8.GetBytes(diag.Count==0?"Nenhuma divergência detectada.":string.Join("\r\n",diag)));Guard.Atomic(Path.Combine(dest,"LEIA-ME.txt"),Encoding.UTF8.GetBytes("Revise DIAGNOSTICO.txt. Client: copiar para a versão ativa Data/InGameShopScript/<versao>. Server: Data/CashShop. Recarregar CashShop no servidor e reabrir o cliente. Exportar não aplica alterações. Este editor não ativa automaticamente produtos/VIP inexistentes.\r\n"));status.Text="Catálogo exportado com diagnóstico: "+dest;}
  string Ask(string title,string label){using(var f=new Form{Text=title,Size=new Size(440,160),StartPosition=FormStartPosition.CenterParent}){var box=new TextBox{Dock=DockStyle.Top};var l=new Label{Text=label,Dock=DockStyle.Top};var ok=new Button{Text="Continuar",Dock=DockStyle.Bottom,DialogResult=DialogResult.OK};f.Controls.Add(box);f.Controls.Add(l);f.Controls.Add(ok);return f.ShowDialog(this)==DialogResult.OK?box.Text:null;}}
