  void DatabasePage(){var p=Page("Contas e personagens");var conn=Bar();sqlHost.Width=150;sqlDb.Width=130;sqlUser.Width=100;sqlPassword.Width=100;sqlPassword.UseSystemPasswordChar=true;integrated.Text="Windows";integrated.Checked=true;integrated.AutoSize=true;trust.Text="Confiar no certificado SQL";trust.AutoSize=true;
