  void LockKeys(DataGridView g){foreach(var name in new[]{"Name","memb___id"})if(g.Columns.Contains(name))g.Columns[name].ReadOnly=true;}
  bool Review(DataTable edited,DataTable before,string title){var changes=new List<string>();foreach(DataColumn col in edited.Columns)if(!Equals(edited.Rows[0][col],before.Rows[0][col]))changes.Add(col.ColumnName+": "+before.Rows[0][col]+" → "+edited.Rows[0][col]);if(db.OriginalCharacter!=null&&edited==charTable&&!db.Inventory.Data.SequenceEqual(db.Inventory.Original)){int count=Enumerable.Range(0,InventoryBlob.Slots).Count(s=>!db.Inventory.Data.Skip(s*25).Take(25).SequenceEqual(db.Inventory.Original.Skip(s*25).Take(25)));changes.Add("Inventário: "+count+" slot(s) alterado(s)");}if(changes.Count==0){status.Text="Nenhuma alteração.";return false;}return MessageBox.Show(this,title+"\r\n\r\n"+string.Join("\r\n",changes)+"\r\n\r\nAplicar? A conta deve estar desconectada.","Revisar alterações",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;}
  void SaveCharacter(){if(charTable==null)throw new Exception("Escolha uma conta e um personagem na aba Contas.");charGrid.EndEdit();BindingContext[charTable].EndCurrentEdit();if(Review(charTable,db.OriginalCharacter,"Personagem "+db.Character)){db.SaveCharacter(charTable);charTable=db.OriginalCharacter.Copy();charTable.Columns.Remove("Inventory");charGrid.DataSource=charTable;LockKeys(charGrid);RefreshInventory();status.Text="Personagem e inventário salvos. Atributos desconhecidos preservados.";}}
