   foreach(var pair in new[]{new KeyValuePair<string,NumericUpDown>("Nível do item (+0..15)",invLevel),new KeyValuePair<string,NumericUpDown>("Durabilidade",invDur),new KeyValuePair<string,NumericUpDown>("Adicional (código 0..7)",invOption),new KeyValuePair<string,NumericUpDown>("Excellent (máscara 0..63)",invExc)}){pane.Controls.Add(new Label{Text=pair.Key,AutoSize=true});pane.Controls.Add(pair.Value);}pane.Controls.Add(invSkill);pane.Controls.Add(invLuck);pane.Controls.Add(Button("Alterar opções do slot",()=>{RequireSlot();db.Inventory.Options(selectedSlot,(int)invLevel.Value,(int)invDur.Value,invSkill.Checked,invLuck.Checked,(int)invOption.Value,(int)invExc.Value);RefreshInventory();}));pane.Controls.Add(new Label{Text="Mover para slot (somente bolsa principal)",AutoSize=true});pane.Controls.Add(moveTarget);pane.Controls.Add(Button("Mover item",()=>{RequireSlot();db.Inventory.Move(selectedSlot,(int)moveTarget.Value,catalog);RefreshInventory();}));
   pane.Controls.Add(Button("Exportar inventário .bin",()=>{RequireCharacter();string f=SaveFile("inventario.bin","Inventário binário|*.bin");if(f!=null)File.WriteAllBytes(f,db.Inventory.Data);}));pane.Controls.Add(Button("Importar inventário .bin",()=>{RequireCharacter();string f=PickFile("Inventário binário|*.bin");if(f==null)return;byte[] b=File.ReadAllBytes(f);if(b.Length!=5975)throw new Exception("Arquivo deve ter 5975 bytes.");db.Inventory.Data=b;RefreshInventory();status.Text="Importado para revisão; ainda não gravado no banco.";}));pane.Controls.Add(Button("Salvar personagem e inventário",()=>SaveCharacter()));
   slotHex.Multiline=true;slotHex.ReadOnly=true;slotHex.Width=285;slotHex.Height=60;pane.Controls.Add(new Label{Text="Bytes do slot (somente leitura)",AutoSize=true});pane.Controls.Add(slotHex);
   invGrid.SelectionChanged+=(s,e)=>{if(loadingSlot||invGrid.CurrentRow==null||db.OriginalCharacter==null)return;selectedSlot=Convert.ToInt32(invGrid.CurrentRow.Cells["Slot"].Value);var b=db.Inventory.Slot(selectedSlot);slotHex.Text=Guard.Hex(b);if(db.Inventory.Empty(selectedSlot))return;invLevel.Value=(b[1]>>3)&15;invDur.Value=b[2];invSkill.Checked=(b[1]&128)!=0;invLuck.Checked=(b[1]&4)!=0;invOption.Value=(b[1]&3)+((b[7]&64)>>4);invExc.Value=b[7]&63;};
  }
  void RequireCharacter(){if(db.OriginalCharacter==null)throw new Exception("Carregue um personagem na aba Contas.");}
  void RequireSlot(){RequireCharacter();if(selectedSlot<0)throw new Exception("Selecione um slot.");}
  void RefreshInventory(){loadingSlot=true;try{var t=new DataTable();foreach(string name in new[]{"Slot","Área","Item","Nível","Durabilidade","Alterado"})t.Columns.Add(name);for(int s=0;s<239;s++){var b=db.Inventory.Slot(s);bool empty=db.Inventory.Empty(s);string area=s<12?"Equipamento":s<76?"Bolsa principal":"Expansão / especial";t.Rows.Add(s,area,empty?"(vazio)":catalog.Name(db.Inventory.Id(s)),empty?"":((b[1]>>3)&15).ToString(),empty?"":b[2].ToString(),b.SequenceEqual(db.Inventory.Original.Skip(s*25).Take(25))?"":"Sim");}invGrid.DataSource=t;selectedSlot=-1;}finally{loadingSlot=false;}}
  void HelpPage(){var page=Page("Ajuda / licença");string doc=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"README.md");page.Controls.Add(new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=BackColor,ForeColor=ForeColor,BorderStyle=BorderStyle.None,Text=File.Exists(doc)?File.ReadAllText(doc):"MU Editor Phoenix 1.2 — MIT. Projeto, conexão, inventário e baú no mesmo aplicativo."});}

  void LoadDemo(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"examples","Item.xml");if(File.Exists(path)){catalog.Load(path);ShowItems("");projectInfo.Text="Demonstração sintética, sem conexão ao servidor.\r\n\r\nItens de exemplo: "+catalog.Items.Count;}}
 }
